<?php require_once 'config.php'; if (!current_user()) redirect('login.php'); $orderId=(int)($_GET['id']??0); $order=null; try{$stmt=db()->prepare('SELECT * FROM orders WHERE id=? AND user_id=?');$stmt->execute([$orderId,current_user()['id']]);$order=$stmt->fetch(); if(!$order)redirect('account.php');$stmt=db()->prepare('SELECT oi.*,p.name FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?');$stmt->execute([$orderId]);$items=$stmt->fetchAll();}catch(Throwable $exception){redirect('account.php');} $pageTitle='Order #'.$orderId;include 'includes/header.php';$steps=['pending'=>'Placed','processing'=>'Processing','shipped'=>'Shipped','delivered'=>'Delivered'];$statuses=array_keys($steps);$current=array_search($order['status'],$statuses,true); ?>
<section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow">Order #<?= $orderId ?></div><h1>On its way to you.</h1><p>Placed <?= e(date('d M Y',strtotime($order['created_at']))) ?> · <?= money($order['total']) ?></p></div><a class="btn btn-outline" href="account.php">Back to account</a></div><div class="order-tracking timeline"><?php foreach($steps as $status=>$label):$index=array_search($status,$statuses,true); ?><article class="tracking-step <?= $index <= $current ? 'complete' : '' ?>"><time><?= $index <= $current ? '✓' : '○' ?></time><h3><?= $label ?></h3><p><?= $index <= $current ? ($status === $order['status'] ? 'Current order status' : 'Complete') : 'Coming next' ?></p></article><?php endforeach; ?></div><div class="summary"><h3>Items in this order</h3><?php foreach($items as $item): ?><div class="summary-line"><span><?= e($item['name']) ?> × <?= (int)$item['quantity'] ?></span><span><?= money($item['unit_price']*$item['quantity']) ?></span></div><?php endforeach; ?><div class="summary-line summary-total"><span>Delivery address</span><span><?= e($order['address']) ?></span></div></div></div></section><?php include 'includes/footer.php'; ?>
